// Controlled visual preview: real frontend + replay fixture generated by the Java smoke test.
// No connection to the real backend or MT5. Node 24 and installed Microsoft Edge only.
import {readFile,writeFile,mkdir,mkdtemp} from 'node:fs/promises';
import {join,dirname} from 'node:path';
import {tmpdir} from 'node:os';
import {spawn} from 'node:child_process';

const [fixtureFile,outputFile,pageUrl='http://localhost:5173/three-candles']=process.argv.slice(2);
if(!fixtureFile||!outputFile) throw new Error('Usage: node captureThreeCandlesStructure.mjs fixture.json screenshot.png [page URL]');
const fixture=JSON.parse(await readFile(fixtureFile,'utf8'));
const profile=await mkdtemp(join(tmpdir(),'three-candles-edge-'));
const browser=spawn(process.env.EDGE_PATH??'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',[
  '--headless=new','--disable-gpu','--no-first-run','--disable-extensions','--remote-debugging-port=0',
  `--user-data-dir=${profile}`,'about:blank',
],{windowsHide:true,stdio:'ignore'});
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
let socket;
try {
  let port;
  for(let i=0;i<100;i++) {
    try {port=(await readFile(join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{await delay(100);}
  }
  if(!port) throw new Error('Edge DevTools did not start');
  const targets=await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
  socket=new WebSocket(targets.find(t=>t.type==='page').webSocketDebuggerUrl);
  await new Promise((resolve,reject)=>{socket.onopen=resolve;socket.onerror=reject;});
  let sequence=0;const pending=new Map(),errors=[];
  function send(method,params={}) {
    return new Promise((resolve,reject)=>{
      const id=++sequence;
      const timeout=setTimeout(()=>{pending.delete(id);reject(new Error(`CDP timeout: ${method}`));},10000);
      pending.set(id,{resolve:v=>{clearTimeout(timeout);resolve(v);},reject:e=>{clearTimeout(timeout);reject(e);}});
      socket.send(JSON.stringify({id,method,params}));
    });
  }
  socket.onmessage=event=>{
    const message=JSON.parse(event.data);
    if(message.id){const p=pending.get(message.id);pending.delete(message.id);if(p)message.error?p.reject(new Error(JSON.stringify(message.error))):p.resolve(message.result);}
    if(message.method==='Runtime.exceptionThrown')errors.push(message.params.exceptionDetails.text);
    if(message.method==='Fetch.requestPaused'){
      const request=message.params;const path=new URL(request.request.url).pathname;
      let data=fixture;
      if(path.endsWith('/history/status'))data={cached:true};
      if(path.endsWith('/config'))data={liveSymbol:'WINZ26',timeframes:[5,15],zone:'America/Sao_Paulo',sessions:[{symbol:fixture.symbol,date:fixture.structure?.preparation?.sessionDate ?? '2026-10-20'}]};
      if(path.endsWith('/live'))data={symbol:'WINZ26',timeframeMinutes:5,status:'UNAVAILABLE',candles:[],structure:{levels:[],totalActive:0,maxLevels:6,selection:'NEAREST_LAST_CLOSED_THEN_LATEST_CONFIRMED',supported:true}};
      void send('Fetch.fulfillRequest',{requestId:request.requestId,responseCode:200,responseHeaders:[
        {name:'Content-Type',value:'application/json'}, {name:'Access-Control-Allow-Origin',value:'*'},
        {name:'Access-Control-Allow-Methods',value:'GET,POST,DELETE,OPTIONS'}, {name:'Access-Control-Allow-Headers',value:'Content-Type'},
      ],body:Buffer.from(JSON.stringify(data)).toString('base64')}).catch(e=>{if(!String(e).includes('Invalid InterceptionId'))errors.push(String(e));});
    }
  };
  await send('Page.enable');await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:1520,height:fixture.structure?.preparation?.experimental?1480:1100,deviceScaleFactor:1,mobile:false});
  await send('Fetch.enable',{patterns:[{urlPattern:'*/api/three-candles/*'}]});
  await send('Page.navigate',{url:pageUrl});
  const evaluate=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true})).result?.value;
  async function waitFor(expression){for(let i=0;i<120;i++){if(await evaluate(expression))return;await delay(100);}throw new Error(`Preview condition failed: ${expression}; errors=${errors}`);}
  await waitFor("Array.from(document.querySelectorAll('button')).some(b=>b.textContent.trim()==='Replay')");
  await delay(500);
  await evaluate("Array.from(document.querySelectorAll('button')).find(b=>b.textContent.trim()==='Replay').click()");
  await waitFor("Array.from(document.querySelectorAll('button')).some(b=>b.textContent.trim()==='Carregar'&&!b.disabled)");
  if(fixture.structure?.preparation?.experimental) {
    await evaluate("Array.from(document.querySelectorAll('[role=combobox]')).find(e=>e.textContent.includes('2+2 (referência)')).dispatchEvent(new MouseEvent('mousedown',{bubbles:true,button:0}))");
    await waitFor("Array.from(document.querySelectorAll('[role=option]')).some(e=>e.textContent.includes('1+1 experimental'))");
    await evaluate("Array.from(document.querySelectorAll('[role=option]')).find(e=>e.textContent.includes('1+1 experimental')).click()");
    await delay(200);
  }
  const cursor=new Date(fixture.availableAtMsc ?? fixture.candles.at(-1).availableAtMsc).toISOString().slice(11,16);
  await evaluate(`(() => {const input=document.querySelector('input[type=time]');Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(input,${JSON.stringify(cursor)});input.dispatchEvent(new Event('input',{bubbles:true}));})()`);
  await delay(200);
  await evaluate("Array.from(document.querySelectorAll('button')).find(b=>b.textContent.trim()==='Carregar').click()");
  await waitFor("document.body.textContent.includes('n\u00edveis exibidos') || document.body.textContent.includes('niveis exibidos')");
  await delay(1000);
  const screenshot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
  await mkdir(dirname(outputFile),{recursive:true});await writeFile(outputFile,Buffer.from(screenshot.data,'base64'));
  // Exercise the actual React controls and canvas delivery, preserving replay state.
  const toggle=async label=>{await evaluate(`Array.from(document.querySelectorAll('label')).find(l=>l.textContent.includes(${JSON.stringify(label)})).querySelector('input').click()`);await delay(300);};
  const saveCheck=async name=>{const shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});const path=outputFile.replace(/\.png$/,`-${name}`);await writeFile(path,Buffer.from(shot.data,'base64'));return path;};
  const comparisonChecks={};
  if(fixture.structure?.preparation?.experimental) {
    await toggle('Adicionais H1 1+1'); comparisonChecks.strictOnly=await saveCheck('strict-only.png');
    await toggle('Referência H1 2+2'); await toggle('Adicionais H1 1+1'); comparisonChecks.additionalOnly=await saveCheck('additional-only.png');
    await toggle('Referência H1 2+2');
  }
  await toggle('H1 -'); const hidden=await saveCheck('h1-preparation-none.png');
  await toggle('H1 -'); const restored=await saveCheck('h1-preparation-restored.png');
  await send('Input.dispatchMouseEvent',{type:'mouseWheel',x:800,y:780,deltaX:-700,deltaY:0});
  await delay(300); const scrolled=await saveCheck('h1-preparation-scrolled.png');
  await send('Input.dispatchMouseEvent',{type:'mouseWheel',x:800,y:780,deltaX:0,deltaY:-300});
  await delay(300); const zoomed=await saveCheck('h1-preparation-zoomed.png');
  const checks={...comparisonChecks,hidden,restored,scrolled,zoomed};
  console.log(JSON.stringify({screenshot:outputFile,checks,levels:fixture.structure.levels.length,errors,source:'controlled real-history replay preview; API intercepted'}));
  await send('Browser.close').catch(()=>{});
} finally {socket?.close();if(browser.exitCode===null)browser.kill();}
